var minimumBoxes = function(n) {
    let curr = 0;
    let h = 0;
    while (curr + Math.floor(((h + 1) * (h + 2)) / 2) <= n) {
        h++;
        curr += Math.floor((h * (h + 1)) / 2);
    }
    let floorBoxes = Math.floor((h * (h + 1)) / 2);
    let rem = n - curr;
    let j = 0;
    while (rem > 0) {
        j++;
        rem -= j;
        floorBoxes++;
    }
    return floorBoxes;
};
